3	import jakarta.validation.Valid;
4	import net.officefloor.plugin.variable.Out;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
7	import org.springframework.validation.annotation.Validated;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Validates before {@link LoadOwner} runs, so an invalid body is a 400 even when the owner does not exist.
12	 *
13	 * <p>Email validity and normalization go through {@link OwnerEmail}, the single authority shared with the
14	 * create pipeline, rather than a bean-validation {@code @Email} constraint, so both pipelines agree.
15	 */
16	@Validated
17	public class ValidateOwner {
18	
19	    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws InvalidEmailException {
21	        // Normalize whichever address form was supplied (structured addressLine1/addressLine2
22	        // preferred, else the flat address) and compose the canonical address, so the update
23	        // stores and returns the same form as the create pipeline.
24	        OwnerAddress.apply(request);
25	        String email = OwnerEmail.normalize(request.getEmail());
26	        if (email != null && !OwnerEmail.isValid(email)) {
27	            throw new InvalidEmailException("Email is not a valid address: " + request.getEmail());
28	        }
29	        if (email != null && OwnerEmail.isDisposableDomain(email)) {
30	            throw new InvalidEmailException(
31	                    "Email domain is a disposable-domain blocklist entry: " + request.getEmail());
32	        }
33	        request.setEmail(email);
34	        validated.set(request);
35	    }
36	}
