9	/**
10	 * Rejects a supplied registrationDate that is later than the server's current date with a
11	 * 400, before any entity is built or persisted. A no-op when no registrationDate is
12	 * supplied (it then defaults to the server's current date in {@link BuildOwner}).
13	 *
14	 * <p>Reads the body published by {@link ValidateNewOwner} rather than binding
15	 * {@code @RequestBody} again, since the HTTP body may be bound only once per pipeline.
16	 */
17	public class ValidateRegistrationDate {
18	
19	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
20	        LocalDate supplied = request.getRegistrationDate();
21	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
22	            throw new FutureRegistrationDateException(
23	                    "registrationDate is later than the server date: " + supplied);
24	        }
25	    }
26	}
