3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	
7	/**
8	 * Validates the owner's {@code postcode} against its city, after the body has been published by
9	 * the preceding validation step. A postcode is optional: an owner created without one is accepted
10	 * unchanged. When present it must be 4 digits and, for a city with a known region, within that
11	 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known
12	 * region accepts any 4-digit postcode. Rejects an out-of-range or malformed postcode with a 400.
13	 */
14	public class ValidatePostcode {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
17	        String postcode = request.getPostcode();
18	        if (!OwnerPostcode.isValid(postcode, request.getCity())) {
19	            throw new InvalidPostcodeException(
20	                    "Postcode is not valid for city '" + request.getCity() + "': " + postcode);
21	        }
22	    }
23	}
