1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	
7	/**
8	 * Runs after {@link ValidateNewOwner} and before {@link ValidateUniqueIdentity}. A read-only
9	 * step that derives the new owner's deterministic {@link Household.Id} from its last name and
10	 * postcode (see {@link Household}) and publishes it for the rest of the pipeline — a present id
11	 * when the request carries a postcode, {@link Household.Id#ABSENT} otherwise. It writes nothing
12	 * to the database.
13	 *
14	 * <p>The household id is now derived purely from {@code (lastName, postcode)}, so every owner
15	 * with a postcode carries one and owners sharing a last name and postcode share it. The gate in
16	 * {@link ValidateUniqueIdentity} rejects a second owner in the same household unless the request
17	 * declares {@code sharesHousehold}; {@link BuildOwner} stamps the resolved id on the new owner.
18	 */
19	public class ResolveHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, Out<Household.Id> householdIdOut) {
22	        householdIdOut.set(Household.idFor(request));
23	    }
24	}
