1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Runs after {@link ResolveHousehold} (which derives the deterministic {@link Household.Id} from
10	 * the request's last name and postcode) and before {@link BuildOwner}. The duplicate-detection
11	 * gate: because a household is now keyed on {@code (lastName, postcode)}, owners sharing a last
12	 * name and postcode are the same household, so a second owner in an existing household is a
13	 * duplicate and is rejected with a 409.
14	 *
15	 * <p>The write-only {@code sharesHousehold} flag only bypasses this block: when set, the new
16	 * owner is created as a declared household member instead of being rejected. Publishes nothing;
17	 * it only escalates on conflict.
18	 */
19	public class ValidateUniqueIdentity {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
22	            OwnerRepository ownerRepository) throws DuplicateIdentityException {
23	        if (householdId == null || !householdId.isPresent()) {
24	            // No postcode means no household, so there is nothing to collide with.
25	            return;
26	        }
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            // Declared household member: bypass the duplicate block.
29	            return;
30	        }
31	        // No self to exclude yet: the new owner is not persisted at this point.
32	        if (Household.hasMember(householdId.value(), null, ownerRepository)) {
33	            throw new DuplicateIdentityException("Household " + householdId.value()
34	                    + " already has an owner (same last name and postcode)");
35	        }
36	    }
37	}
