1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Runs after {@link ValidateUniqueIdentity} and before {@link BuildOwner}. A read-only
11	 * validation gate: rejects the create with a 409 when the owner's city already contains 50
12	 * or more owners (compared case-insensitively), so no city grows past capacity. Publishes
13	 * nothing; it only escalates on conflict.
14	 */
15	public class ValidateCityCapacity {
16	
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (city.equalsIgnoreCase(existing.getCity())) {
25	                count++;
26	            }
27	        }
28	        if (count >= CITY_CAPACITY) {
29	            throw new CityAtCapacityException(
30	                    "City " + city + " already contains " + CITY_CAPACITY + " or more owners");
31	        }
32	    }
33	}
