6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Populates the response-only {@link Owner#isBulkSignupWarning() bulkSignupWarning} flag:
11	 * true once more than 80 owners have already been created today, otherwise false. "Today"
12	 * is the current, weekend-adjusted business day (matching how {@link BuildOwner} stores and
13	 * {@link ValidateDailyOwnerLimit} buckets registration dates), and the count is of owners
14	 * whose {@code registrationDate} falls on that day. Mutates the loaded owner in place so the
15	 * responder's mapper carries the flag onto the DTO.
16	 */
17	public class FlagBulkSignup {
18	
19	    private static final int BULK_THRESHOLD = 80;
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        LocalDate today = BusinessDay.effectiveRegistrationDate(null);
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (today.equals(existing.getRegistrationDate())) {
26	                count++;
27	            }
28	        }
29	        owner.setBulkSignupWarning(count > BULK_THRESHOLD);
30	    }
31	}
