3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Populates the response-only {@link Owner#isPossibleDuplicate() possibleDuplicate} and
9	 * {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} fields from the shared
10	 * {@link PossibleDuplicate} rule: true, with the matching owner id, when this owner shares an
11	 * existing owner's last name and postcode with a different telephone; otherwise false with no
12	 * id. A declared household member is never flagged (see {@link PossibleDuplicate}). Mutates the
13	 * loaded owner in place so the responder's mapper carries the flag onto the DTO.
14	 */
15	public class FlagPossibleDuplicate {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        Integer match = PossibleDuplicate.matchOf(owner, ownerRepository);
19	        owner.setPossibleDuplicate(match != null);
20	        owner.setPossibleDuplicateOf(match);
21	    }
22	}
