269	     * value rewritten as the country code, a space, then the national digits grouped in threes
270	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
271	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
272	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
273	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
274	     * derived from {@link #getTelephone()}.
275	     */
276	    @Transient
277	    public String getTelephoneDisplay() {
278	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
279	            return null;
280	        }
281	        String digits = this.telephone.substring(1);
282	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
283	        if (digits.length() <= countryCodeLength) {
284	            return this.telephone;
285	        }
286	        String countryCode = digits.substring(0, countryCodeLength);
287	        String national = digits.substring(countryCodeLength);
288	        StringBuilder grouped = new StringBuilder();
289	        for (int i = 0; i < national.length(); i++) {
290	            if (i > 0 && i % 3 == 0) {
291	                grouped.append(' ');
292	            }
293	            grouped.append(national.charAt(i));
294	        }
295	        return "+" + countryCode + " " + grouped;
296	    }
