332	    /**
333	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
334	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
335	     * Not persisted — derived from {@link #getCustomerCode()}.
336	     */
337	    @Transient
338	    public int getCheckDigit() {
339	        int sum = 0;
340	        boolean dbl = true;
341	        String code = this.customerCode == null ? "" : this.customerCode;
342	        for (int i = code.length() - 1; i >= 0; i--) {
343	            char c = code.charAt(i);
344	            if (c < '0' || c > '9') {
345	                continue;
346	            }
347	            int d = c - '0';
348	            if (dbl) {
349	                d *= 2;
350	                if (d > 9) {
351	                    d -= 9;
352	                }
353	            }
354	            sum += d;
355	            dbl = !dbl;
356	        }
357	        return (10 - (sum % 10)) % 10;
358	    }
