371	        int points = 0;
372	        boolean hasEmail = this.email != null && !this.email.isBlank();
373	        if (hasEmail) {
374	            points += 2;
375	        }
376	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
377	        if (uniqueName) {
378	            points += 1;
379	        }
380	        if (this.householdSize != null && this.householdSize >= 3) {
381	            points += 2;
382	        }
383	        if (this.registrationDate != null
384	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate) >= 1) {
385	            points += 3;
