419	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
420	     */
421	    private static final Map<String, int[]> REGION_RANGE = Map.of(
422	        "NSW", new int[] {2000, 2099},
423	        "VIC", new int[] {3000, 3099},
424	        "QLD", new int[] {4000, 4099});
