426	    /**
427	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
428	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
429	     */
430	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
431	        "NSW", "Australia/Sydney",
432	        "VIC", "Australia/Melbourne",
433	        "QLD", "Australia/Brisbane");
