435	    /**
436	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
437	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
438	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
439	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
440	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
441	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
442	     * by the owner pipelines (e.g. postcode validation) rather than copied.
443	     */
444	    public static String regionFor(String postcode, String city) {
445	        String region = regionForPostcode(postcode);
446	        if (region != null) {
447	            return region;
448	        }
449	        String cityRegion = regionForCity(city);
450	        return cityRegion != null ? cityRegion : "UNKNOWN";
451	    }
