453	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
454	     * Brisbane->QLD), or {@code null} when the city has no known region. */
455	    public static String regionForCity(String city) {
456	        return city == null ? null : CITY_REGION.get(city);
457	    }
