459	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
460	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
461	     * range. */
462	    public static String regionForPostcode(String postcode) {
463	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
464	            return null;
465	        }
466	        int value = Integer.parseInt(postcode);
467	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
468	            int[] range = entry.getValue();
469	            if (value >= range[0] && value <= range[1]) {
470	                return entry.getKey();
471	            }
472	        }
473	        return null;
474	    }
