25	    /**
26	     * The household identifier published between steps. A dedicated type keeps the variable
27	     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
28	     * the pipeline. {@link #ABSENT} (an empty value) means the new owner has no postcode and
29	     * therefore no household.
30	     */
31	    record Id(String value) {
32	
33	        static final Id ABSENT = new Id("");
34	
35	        boolean isPresent() {
36	            return this.value != null && !this.value.isBlank();
37	        }
38	    }
39	
40	    /**
41	     * Stable identifier for the request's household: the first 12 upper-case hex characters of
42	     * the SHA-256 of {@code normalizedLastName + "|" + postcode}, so every owner with the same
43	     * last name and postcode derives the same value regardless of creation order.
44	     * {@link Id#ABSENT} when the request carries no postcode (no postcode means no household).
45	     */
46	    static Id idFor(OwnerFieldsDto request) {
47	        String postcode = normalizePostcode(request.getPostcode());
48	        if (postcode == null) {
49	            return Id.ABSENT;
50	        }
51	        String seed = normalizeName(request.getLastName()) + "|" + postcode;
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder();
56	            for (int i = 0; i < 6; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return new Id(sb.toString());
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	    }
65	
66	    /**
67	     * Whether an owner other than {@code exclude} already carries {@code householdId}. The single
68	     * household-membership lookup, shared by the duplicate gate ({@link ValidateUniqueIdentity},
69	     * which passes {@code exclude = null} because the new owner is not yet persisted) and the
70	     * soft-match rule ({@link PossibleDuplicate}, which excludes the owner itself). Always
71	     * {@code false} for a {@code null}/blank id (an owner with no postcode has no household).
72	     * Scans only {@link ActiveOwners active owners}, so a soft-deleted owner no longer blocks a
73	     * household create.
74	     */
75	    static boolean hasMember(String householdId, Owner exclude, OwnerRepository ownerRepository) {
76	        if (householdId == null || householdId.isBlank()) {
77	            return false;
78	        }
79	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
80	            if (exclude != null && exclude.getId() != null && exclude.getId().equals(existing.getId())) {
81	                continue;
82	            }
83	            if (householdId.equals(existing.getHouseholdId())) {
84	                return true;
85	            }
86	        }
87	        return false;
88	    }
89	
90	    /**
91	     * The number of owners carrying {@code householdId}. The single household-size lookup, reused
92	     * wherever the membership points rule needs a household's member count. {@code 0} for a
93	     * {@code null}/blank id (an owner with no postcode has no household). Scans only
94	     * {@link ActiveOwners active owners}, consistent with {@link #hasMember}, so a soft-deleted
95	     * owner does not count towards a household's size.
96	     */
97	    static int size(String householdId, OwnerRepository ownerRepository) {
98	        if (householdId == null || householdId.isBlank()) {
99	            return 0;
100	        }
101	        int count = 0;
102	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
103	            if (householdId.equals(existing.getHouseholdId())) {
104	                count++;
105	            }
106	        }
107	        return count;
108	    }
109	
110	    /**
111	     * Normalize a last name for the household key: trim, collapse any run of whitespace to a
112	     * single space, and lower-case. Yields {@code ""} for a {@code null} input.
113	     */
114	    private static String normalizeName(String value) {
115	        if (value == null) {
116	            return "";
117	        }
118	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
119	    }
120	
121	    /** Trimmed postcode, or {@code null} when absent/blank (no postcode means no household). */
122	    private static String normalizePostcode(String value) {
123	        if (value == null || value.isBlank()) {
124	            return null;
125	        }
126	        return value.trim();
127	    }
128	}
