public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
        OwnerRepository ownerRepository) throws DuplicateIdentityException {
    if (householdId == null || !householdId.isPresent()) return;          // no postcode => no household
    if (Boolean.TRUE.equals(request.getSharesHousehold())) return;         // declared member bypasses
    if (Household.hasMember(householdId.value(), null, ownerRepository))
        throw new DuplicateIdentityException("Household " + householdId.value() + " already has an owner (same last name and postcode)");
}
