3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
15	 * required field (firstName, lastName, an address in either form, city, telephone) with a 400
16	 * listing the offending field names, normalizes the telephone to E.164 form (400 if it cannot
17	 * form a valid E.164 number), then publishes the body for {@link BuildOwner}.
18	 *
19	 * <p>Runs before {@link BuildOwner} and binds {@code @RequestBody} without {@code @Valid}
20	 * so the required-field check produces the {@code errors} response shape rather than the
21	 * generic schema-validation shape, and so an invalid body is a 400 here.
22	 */
23	public class ValidateNewOwner {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        // Normalize the address up front so the required-field check sees the canonical form
28	        // (an address blank after normalization is rejected) and every later step — storage,
29	        // the response and household comparisons — carries the same normalized value. The
30	        // structured addressLine1/addressLine2 are preferred when supplied, falling back to the
31	        // flat address; the composed address is what the later steps carry.
32	        OwnerAddress.apply(request);
33	        List<String> missing = new ArrayList<>();
34	        if (isBlank(request.getFirstName())) {
35	            missing.add("firstName");
36	        }
37	        if (isBlank(request.getLastName())) {
38	            missing.add("lastName");
39	        }
40	        // Accepted in either form: a non-blank structured addressLine1, or the flat address.
41	        // OwnerAddress.apply has composed the effective address, so a blank address means
42	        // neither form supplied one.
43	        if (isBlank(request.getAddress())) {
44	            missing.add("address");
45	        }
46	        if (isBlank(request.getCity())) {
47	            missing.add("city");
48	        }
49	        if (isBlank(request.getTelephone())) {
50	            missing.add("telephone");
51	        }
52	        if (!missing.isEmpty()) {
53	            throw new MissingOwnerFieldsException(missing);
54	        }
55	        String e164 = OwnerTelephone.normalize(request.getTelephone());
56	        if (e164 == null) {
57	            throw new InvalidTelephoneException(
58	                    "Telephone is not a valid E.164 number: " + request.getTelephone());
59	        }
60	        request.setTelephone(e164);
61	        String email = OwnerEmail.normalize(request.getEmail());
62	        if (email != null && !OwnerEmail.isValid(email)) {
63	            throw new InvalidEmailException("Email is not a valid address: " + request.getEmail());
64	        }
65	        if (email != null && OwnerEmail.isDisposableDomain(email)) {
66	            throw new InvalidEmailException(
67	                    "Email domain is a disposable-domain blocklist entry: " + request.getEmail());
68	        }
69	        request.setEmail(email);
70	        validated.set(request);
71	    }
72	
73	    private static boolean isBlank(String value) {
74	        return value == null || value.isBlank();
75	    }
76	}
